    1: namespace InvoiceApp.Domain;
    2: 
    3: /// <summary>
    4: /// Moves an invoice through its lifecycle: Draft -> PendingApproval -> Approved or Rejected.
    5: /// One invoice at a time, decided as a whole by a single approver.
    6: /// </summary>
    7: public class ApprovalService
    8: {
    9:     private readonly IInvoiceRepository _repository;
   10: 
   11:     public ApprovalService(IInvoiceRepository repository)
   12:     {
   13:         _repository = repository;
   14:     }
   15: 
   16:     public Invoice Submit(string invoiceId)
   17:     {
   18:         var invoice = Find(invoiceId);
   19: 
   20:         if (invoice.Status != InvoiceStatus.Draft)
   21:         {
   22:             throw new InvalidOperationException(
   23:                 $"Invoice {invoiceId} is {invoice.Status}; only drafts can be submitted.");
   24:         }
   25: 
   26:         invoice.Status = InvoiceStatus.PendingApproval;
   27:         _repository.Update(invoice);
   28:         return invoice;
   29:     }
   30: 
   31:     public Invoice Approve(string invoiceId, string approver, ApproverRole role)
   32:     {
   33:         var invoice = Find(invoiceId);
   34:         EnsurePending(invoice);
   35: 
   36:         var limit = ApprovalLimits.GetLimit(role);
   37:         if (invoice.Amount > limit)
   38:         {
   39:             throw new ApprovalRejectedException(
   40:                 $"{role} cannot approve invoice amount {invoice.Amount.ToString("N2", System.Globalization.CultureInfo.InvariantCulture)} because the approval limit is {limit.ToString("N2", System.Globalization.CultureInfo.InvariantCulture)}.");
   41:         }
   42: 
   43:         invoice.Status = InvoiceStatus.Approved;
   44:         invoice.DecidedBy = approver;
   45:         invoice.DecidedAt = DateTime.UtcNow;
   46:         _repository.Update(invoice);
   47:         return invoice;
   48:     }
   49: 
   50:     public Invoice Reject(string invoiceId, string approver, string reason)
   51:     {
   52:         if (string.IsNullOrWhiteSpace(reason))
   53:         {
   54:             throw new ArgumentException("A reason is required to reject an invoice.", nameof(reason));
   55:         }
   56: 
   57:         var invoice = Find(invoiceId);
   58:         EnsurePending(invoice);
   59: 
   60:         invoice.Status = InvoiceStatus.Rejected;
   61:         invoice.DecidedBy = approver;
   62:         invoice.DecidedAt = DateTime.UtcNow;
   63:         invoice.DecisionNote = reason;
   64:         _repository.Update(invoice);
   65:         return invoice;
   66:     }
   67: 
   68:     private Invoice Find(string invoiceId) =>
   69:         _repository.GetById(invoiceId)
   70:         ?? throw new KeyNotFoundException($"Invoice {invoiceId} was not found.");
   71: 
   72:     private static void EnsurePending(Invoice invoice)
   73:     {
   74:         if (invoice.Status != InvoiceStatus.PendingApproval)
   75:         {
   76:             throw new InvalidOperationException(
   77:                 $"Invoice {invoice.Id} is {invoice.Status}; only pending invoices can be decided.");
   78:         }
   79:     }
   80: }
